insert into korekta_jowes values
    (1, 1, 'wybor', 'Czym działalność odpłatna pożytku publicznego różni się od działalności gospodarczej w fundacji lub stowarzyszeniu?', 40, '{"poprawna": 3, "odpowiedzi": ["Niczym – to dwie nazwy tej samej działalności.", "W działalności odpłatnej nie wolno zatrudniać pracowników, w gospodarczej już tak.", "Odpłatną może prowadzić tylko spółdzielnia socjalna, a gospodarczą tylko fundacja.", "Odpłatna nie może przynosić zysku (cena pokrywa najwyżej koszty bezpośrednie), a gospodarcza może i wymaga wpisu do rejestru przedsiębiorców KRS."], "wyjasnienie": "Działalność odpłatna to zadania pożytku publicznego za opłatą – bez zysku. Gdy cena przekroczy koszty bezpośrednie, z mocy ustawy staje się gospodarczą. Gospodarcza może dawać zysk na cele statutowe, ale wymaga wpisu do rejestru przedsiębiorców KRS."}'::jsonb),
    (2, 1, 'ciekawostka', 'Odpłatna czy gospodarcza? Ściąga', null::int, '{"tekst": "**Działalność odpłatna pożytku publicznego**\n• Tylko zadania pożytku publicznego wpisane do statutu.\n• Cena najwyżej na poziomie kosztów bezpośrednich – **bez zysku**.\n• Cały przychód idzie na działalność pożytku publicznego.\n• **Nie wymaga** wpisu do rejestru przedsiębiorców.\n\n**Działalność gospodarcza**\n• **Może przynosić zysk** – w NGO idzie on na cele statutowe.\n• **Wymaga wpisu** do rejestru przedsiębiorców KRS.\n\n> **Uwaga:** gdy cena w odpłatnej przekroczy koszty bezpośrednie, z mocy prawa staje się ona **gospodarczą** (art. 9 ustawy o działalności pożytku publicznego i o wolontariacie).\n\nPrzykład: warsztat kosztuje 50 zł od osoby. Bilet za **50 zł = odpłatna**, za **80 zł = gospodarcza**."}'::jsonb),
    (3, 1, 'wybor', 'Ile wynosi oprocentowanie preferencyjnej pożyczki BGK dla Podmiotów Ekonomii Społecznej?', 20, '{"poprawna": 0, "odpowiedzi": ["0,25%", "2%", "1,5%", "3%"], "wyjasnienie": "Stałe 0,25% w skali roku, bez prowizji i bez kosztów administracyjnych."}'::jsonb),
    (4, 1, 'ciekawostka', 'Pożyczki dla PES – ściąga', null::int, '{"tekst": "**Preferencyjna pożyczka BGK** • „Na start” (1. rok): max 2 × 100 tys. zł, spłata do 5 lat. • „Na rozwój”: do **2 mln zł**, spłata do 7 lat (do **10 lat** powyżej 400 tys. zł). • Oprocentowanie **0,25%** stałe, bez prowizji i opłat. • Karencja do 6 miesięcy, **weksel obowiązkowo**."}'::jsonb),
    (5, 1, 'wybor', 'Kto jest właściwy do nadania statusu przedsiębiorstwa społecznego?', 25, '{"poprawna": 1, "odpowiedzi": ["Prezydent miasta właściwy dla siedziby organizacji", "Wojewoda", "Starosta właściwy dla miejsca prowadzenia działalności", "Marszałek województwa"], "wyjasnienie": "Status PS nadaje wojewoda w drodze decyzji administracyjnej, według siedziby podmiotu – u nas to Wojewoda Śląski."}'::jsonb),
    (6, 1, 'wybor', 'Rozwiń właściwie skrót: CIS', 20, '{"poprawna": 3, "odpowiedzi": ["Taxus – rodzaj roślin z rodziny cisowatych", "Częstochowska Izba Społeczna", "Centralna Innowacja Społeczna", "Centrum Integracji Społecznej"], "wyjasnienie": "Centrum Integracji Społecznej to placówka realizująca program reintegracji społeczno-zawodowej dla osób zagrożonych wykluczeniem społecznym."}'::jsonb),
    (7, 1, 'wybor', 'Do kiedy przedsiębiorstwo społeczne musi złożyć coroczne sprawozdanie, aby utrzymać status PS?', 20, '{"poprawna": 1, "odpowiedzi": ["Do 31 grudnia", "Do 31 marca", "Do 31 stycznia", "Do 31 czerwca"], "wyjasnienie": "Do 31 marca roku następującego po roku sprawozdawczym. Niezłożenie sprawozdania grozi utratą statusu PS. A 31 czerwca w ogóle nie istnieje!"}'::jsonb),
    (8, 1, 'wybor', 'Wskaż przedsiębiorstwa społeczne z naszego subregionu realizujące usługi społeczne z zakresu kultury.', 40, '{"poprawna": 0, "odpowiedzi": ["Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha, Fundacja Gutenberg na rzecz Kultury i Nauki", "Spółdzielnia Socjalna „Jasne, że bus”, Stowarzyszenie Pomocy Potrzebującym „Podaj dalej”", "Śląska Fundacja Wspierania Rozwoju Społeczno-Zawodowego Juventas, Fundacja Talbota", "Fundacja Pomocy Kobietom EuroHelp, Fundacja Animalove"], "wyjasnienie": "Usługi z zakresu kultury realizują Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha i Fundacja Gutenberg na rzecz Kultury i Nauki."}'::jsonb),
    (9, 1, 'wybor', 'Co oznacza skrót BUR?', 20, '{"poprawna": 1, "odpowiedzi": ["Biuro Usług Regionalnych", "Baza Usług Rozwojowych", "Bank Uniwersalnych Rozwiązań", "Baza Umów Rekrutacyjnych"], "wyjasnienie": "BUR to Baza Usług Rozwojowych prowadzona przez PARP – szkolenia i doradztwo z dofinansowaniem. Szkolenia z możliwością dofinansowania realizuje też uczestnik Forum – Invelion Sp. z o.o."}'::jsonb),
    (10, 1, 'wybor', 'Które z wymienionych przedsiębiorstw społecznych działają na rzecz ekologii i zrównoważonego rozwoju?', 35, '{"poprawna": 3, "odpowiedzi": ["Invelion Sp. z o.o., Fundacja Talbota", "Spółdzielnia Socjalna „Jasne, że zmiana”, Stowarzyszenie Wzajemnej Pomocy „Agape”", "Fundacja Kreatywna Przestrzeń, Fundacja Twoja Zagata", "Fundacja Eko-Logiczna, Fundacja Rething"], "wyjasnienie": "Ekologią zajmują się Fundacja Eko-Logiczna i Fundacja Rething. „Agape” pomaga osobom w kryzysie, a Twoja Zagata prowadzi ranczo z edukacją i animacjami dla dzieci."}'::jsonb),
    (11, 2, 'wielokrotny', 'Zaznacz WSZYSTKIE lokale gastronomiczne z subregionu północnego, które prowadzą podmioty ekonomii społecznej.', 40, '{"poprawna": [0, 2, 4, 6], "odpowiedzi": ["Pieczone Kopytko", "Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha", "Klubokawiarnia Alternatywa 21", "Firma Handlowo-Usługowa SIN-BUD sp. z o.o.", "Art of Dining", "Fundacja Rething", "Niebo w Mieście Częstochowa"]}'::jsonb),
    (12, 2, 'ciekawostka', 'Gastronomia z misją – gdzie zjeść i co robią', null::int, '{"tekst": "**Pieczone Kopytko** (Fundacja Talbota) · Częstochowa, ul. Powstańców Warszawy 147\nTradycyjna kuchnia polska, specjalność: **ręcznie robione pieczone kopytka**. Pomaga osobom wykluczonym wrócić do pracy.\n\n**Niebo w Mieście** · Częstochowa, ul. Targowa 1\nRestauracja i kawiarnia z **kuchnią włoską w zabytkowej kamienicy**. Imprezy okolicznościowe i dowóz.\n\n> **Dobrze wiedzieć:** podmiot ekonomii społecznej to nie zawsze przedsiębiorstwo społeczne. Klubokawiarnię Alternatywa 21 prowadzi **ZAZ**, a Fundacja Art of Dining status PS **dopiero uzyska** – trzymamy kciuki!"}'::jsonb),
    (13, 2, 'wielokrotny', 'Które formy wsparcia JOWES organizuje cyklicznie? Zaznacz wszystkie poprawne.', 30, '{"poprawna": [0, 1, 2, 3], "odpowiedzi": ["Rajd Podmiotów Ekonomii Społecznej", "NGO w Akcji", "Forum Współpracy Przedsiębiorstw Społecznych", "NGO Marketing Days"], "wyjasnienie": "Wszystkie cztery! Rajd PES, NGO w Akcji, Forum Współpracy Przedsiębiorstw Społecznych (właśnie na nim jesteśmy) i NGO Marketing Days – coroczne spotkanie o marketingu, organizowane od 2015 roku."}'::jsonb),
    (14, 2, 'wielokrotny', 'Które z tych podmiotów prowadzą jednostkę reintegracyjną – zakład aktywności zawodowej (ZAZ) albo centrum integracji społecznej (CIS)? Zaznacz wszystkie poprawne.', 35, '{"poprawna": [0, 2, 3], "odpowiedzi": ["Stowarzyszenie YAVA", "VERTO Biuro Rachunkowe Sp. z o.o.", "Klubokawiarnia Alternatywa 21", "Fundacja „Przyjaciel z Sercem”", "Premium Tour Szymczyk Sp. z o.o.", "Fundacja Q Marzeniom"], "wyjasnienie": "YAVA prowadzi ZAZ, w którym pracuje 29 osób z niepełnosprawnością znaczną i umiarkowaną. Klubokawiarnię Alternatywa 21 też prowadzi ZAZ. Fundacja „Przyjaciel z Sercem” prowadzi CIS – Centrum Integracji Społecznej."}'::jsonb),
    (15, 2, 'wielokrotny', 'Kto zadba o Wasze zdrowie i dobrą formę? Zaznacz wszystkie poprawne.', 35, '{"poprawna": [0, 2, 4], "odpowiedzi": ["Kinesis Sp. z o.o.", "Sin-Bud Sp. z o.o.", "Fundacja Doktor Elsner", "Fundacja „Rozwijamy Talenty”", "Fundacja Propagowania Zdrowego Odżywiania MIDEX", "Eco Renewal Sp. z o.o."], "wyjasnienie": "Kinesis – fizjoterapia, rehabilitacja i siłownia; Doktor Elsner – dietetyka kliniczna i profilaktyka; MIDEX – edukacja o zdrowym odżywianiu. „Rozwijamy Talenty” to edukacja i kultura."}'::jsonb),
    (16, 2, 'wielokrotny', 'Które z tych podmiotów mają ofertę dla seniorów? Zaznacz wszystkie poprawne.', 40, '{"poprawna": [0, 2, 4], "odpowiedzi": ["Fundacja Czas na Seniora", "Eco Renewal Sp. z o.o.", "MIMAWI Sp. z o.o.", "Invelion Sp. z o.o.", "Premium Tour Szymczyk Sp. z o.o."], "wyjasnienie": "Czas na Seniora („Razem łatwiej!” – Taksówka Społeczna, „Złota Rączka”), MIMAWI (zajęcia aktywizacyjne dla seniorów), Premium Tour Szymczyk (turystyka dla seniorów)"}'::jsonb),
    (17, 3, 'szacowanie', 'Ile osób co najmniej musi zatrudniać przedsiębiorstwo społeczne?', 25, '{"max": 10, "min": 1, "krok": 1, "poprawna": 3, "jednostka": null, "tolerancja": 3, "wyjasnienie": "Minimum 3 osoby na umowę o pracę lub spółdzielczą umowę o pracę, co najmniej na ¼ etatu. Co najmniej 30% zatrudnionych to osoby z grup zagrożonych wykluczeniem."}'::jsonb),
    (18, 3, 'szacowanie', 'Ile procent zatrudnionych w PS muszą co najmniej stanowić osoby z grup zagrożonych wykluczeniem?', 25, '{"max": 100, "min": 0, "krok": 5, "poprawna": 30, "jednostka": null, "tolerancja": 25, "wyjasnienie": "Co najmniej 30% pracowników PS to m.in. osoby bezrobotne, z niepełnosprawnościami, młodzi do 30 lat i osoby 50+."}'::jsonb),
    (19, 3, 'szacowanie', 'Ile tysięcy złotych wynosi łączne wsparcie JOWES na utworzenie i utrzymanie jednego pełnoetatowego miejsca pracy w naborze 2026?', 25, '{"max": 150, "min": 40, "krok": 1, "poprawna": 87, "jednostka": null, "tolerancja": 30, "wyjasnienie": "43 814 zł na utworzenie + 43 254 zł na utrzymanie przez 12 miesięcy = 87 068 zł."}'::jsonb),
    (20, 3, 'ciekawostka', 'Skąd się bierze 87 068 zł?', null::int, '{"tekst": "43 814 zł – utworzenie miejsca pracy (wyposażenie, sprzęt, adaptacja, środki obrotowe)\n+ 43 254 zł – utrzymanie: pełny etat przez 12 miesięcy (wynagrodzenie, składki, czynsz, media)\n= **87 068 zł na jedno pełnoetatowe miejsce pracy**\n\n• Obie stawki bierze się **tylko łącznie**.\n• Trwałość: 12 miesięcy utrzymania + 6 miesięcy po finansowaniu = **18 miesięcy**.\n• Niepełny etat: ¾ etatu – 32 441 zł, ½ etatu – 21 627 zł.\n• Jeden PS może w naborze dostać wsparcie na **maks. 5 miejsc pracy**.\n• Dodatkowo: refundacja Indywidualnego Planu Reintegracji do **10 800 zł**.\n\n> Kwoty to stawki jednostkowe po indeksacji – źródło: jowes.pl/dotacje2026."}'::jsonb),
    (21, 3, 'szacowanie', 'Ile miejsc pracy w PES/PS JOWES pomógł utworzyć w samym 2026 roku?', 25, '{"max": 100, "min": 0, "krok": 1, "poprawna": 44, "jednostka": null, "tolerancja": 25, "wyjasnienie": "44 miejsca pracy i prawie 3,9 mln zł dotacji dla NGO w 2026 roku. Do tego ponad 3 tys. godzin doradztwa i 14 dni szkoleniowych."}'::jsonb),
    (22, 3, 'szacowanie', 'Ile miejsc pracy powstało w PES/PS dzięki JOWES od 2013 roku?', 25, '{"max": 800, "min": 200, "krok": 10, "poprawna": 570, "jednostka": null, "tolerancja": 150, "wyjasnienie": "570 miejsc pracy i ponad 28,6 mln zł dotacji dla NGO we wszystkich czterech edycjach JOWES (od 2013 r.). Sam obecny projekt (od 2024 r.) to już 177 miejsc pracy."}'::jsonb),
    (23, 4, 'pary', 'Połącz osobę z zespołu JOWES z jej stanowiskiem.', 45, '{"lewe": ["Emilia Konstanciak", "Łukasz Bednarczyk", "Zbyszko Kabziński", "Magdalena Trzepizur"], "prawe": ["Animator", "Doradca marketingowy", "Doradca kluczowy", "Kierownik JOWES"], "poprawna": [3, 2, 1, 0], "wyjasnienie": "Pełny skład i role: jowes.pl/nasz-zespol."}'::jsonb),
    (24, 4, 'pary', 'Kto czym się zajmuje? Część 1', 45, '{"lewe": ["Fundacja Algiz", "Adullam Sp. z o.o.", "Fundacja Dzieci Wuja Toma", "VERTO Biuro Rachunkowe Sp. z o.o."], "prawe": ["Terapie dzieci z niepełnosprawnościami", "Księgowość i rachunkowość", "Wczesne wspomaganie rozwoju dzieci", "Usługi porządkowe i ogrodnicze"], "poprawna": [2, 3, 0, 1], "wyjasnienie": "Algiz – wczesne wspomaganie rozwoju dzieci, Adullam – usługi porządkowe i ogrodnicze, Dzieci Wuja Toma – terapie dzieci z niepełnosprawnościami, VERTO – księgowość, kadry i płace (ok. 60% klientów to NGO i PS)."}'::jsonb),
    (25, 4, 'pary', 'Kto czym się zajmuje? Część 2', 45, '{"lewe": ["Fundacja Muzyki Niezależnej", "Fundacja Propagowania Zdrowego Odżywiania MIDEX", "Fundacja Doktor Elsner", "Fundacja Kreatywna Przestrzeń"], "prawe": ["Szycie i znakowanie odzieży dla firm", "Dietetyka kliniczna i profilaktyka zdrowotna", "Nagłośnienie koncertów i wydawnictwo muzyczne", "Wędliny, garmażeria i catering"], "poprawna": [2, 3, 1, 0], "wyjasnienie": "Muzyka Niezależna – obsługa wydarzeń i wydawnictwo; MIDEX – produkcja spożywcza, catering, edukacja żywieniowa; Doktor Elsner – zdrowie funkcjonalne i dietetyka; Kreatywna Przestrzeń – szycie dla firm, a z zarobku finansuje warsztaty dla dzieci."}'::jsonb),
    (26, 4, 'pary', 'Kto czym się zajmuje? Część 3', 45, '{"lewe": ["Osikowa Dolina Sp. z o.o.", "Fundacja „Dzikie Serce”", "Fundacja Ecostructure", "Niebo w Mieście Sp. z o.o."], "prawe": ["Pracownia rękodzieła i warsztaty artystyczne", "Restauracja z kuchnią włoską", "Dekoracje i warsztaty z drewna topoli osiki", "Budownictwo szkieletowe i ekologiczne"], "poprawna": [2, 0, 3, 1], "wyjasnienie": "Osikowa Dolina – dekoracje z wiórków osikowych; Dzikie Serce – rękodzieło i warsztaty; Ecostructure – budownictwo szkieletowe i ekologiczne; Niebo w Mieście – restauracja i kawiarnia w zabytkowej kamienicy."}'::jsonb),
    (27, 4, 'kolejnosc', 'Jakie są etapy uzyskiwania dotacji w JOWES? Ułóż je we właściwej kolejności.', 40, '{"elementy": ["Biznesplan", "Podpisanie umowy", "Formularz Pomysłu", "Przelew środków"], "poprawna": [2, 0, 1, 3], "wyjasnienie": "Najpierw Formularz Pomysłu, potem biznesplan, podpisanie umowy i na końcu przelew środków."}'::jsonb),
    (28, 5, 'prawda_falsz', 'Dominika Kasiura jest doradcą biznesowym w JOWES.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (29, 5, 'prawda_falsz', 'JOWES prowadzi Agencja Rozwoju Regionalnego w Częstochowie.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (30, 5, 'prawda_falsz', 'JOWES działa w powiatach częstochowskim, kłobuckim i lublinieckim.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (31, 5, 'prawda_falsz', 'Strona internetowa JOWES to jowes.org.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (32, 5, 'prawda_falsz', 'JOWES mieści się w Kamienicy Kupieckiej.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (33, 5, 'prawda_falsz', 'Obecny projekt JOWES objął już wsparciem 241 PES.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (34, 5, 'prawda_falsz', 'Trwałość miejsca pracy z dotacji JOWES to łącznie 24 miesiące.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (35, 5, 'prawda_falsz', 'Każde przedsiębiorstwo społeczne musi mieć organ konsultacyjno-doradczy.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (36, 5, 'prawda_falsz', 'Fundacja Kinesis i Kinesis Sp. z o.o. to ta sama organizacja.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (37, 5, 'prawda_falsz', 'Fundacja Kuźnia Pomysłów prowadzi zajęcia z alpakami.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (38, 5, 'prawda_falsz', 'Stowarzyszenie Wzajemnej Pomocy „Agape” powstało w 1993 r. z inicjatywy osób, które same przeszły kryzys.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (39, 5, 'prawda_falsz', 'Fundacja Czas na Seniora prowadzi biuro rachunkowe.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (40, 5, 'prawda_falsz', 'Spółdzielnia Socjalna „Jasne, że dom i wnętrze” działa w branży remontowo-budowlanej.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (41, 5, 'prawda_falsz', 'Stowarzyszenie Pomocy Osobom z Autyzmem i Stowarzyszenie „Druga Szansa” działają w branży remontowo-budowlanej.', 20, '{"poprawna": 1, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb),
    (42, 5, 'prawda_falsz', 'Fundacja Projekt: Rozwój świadczy usługi sprzątania i organizuje atrakcje dla dzieci.', 20, '{"poprawna": 0, "odpowiedzi": ["Prawda", "Fałsz"]}'::jsonb);
insert into public.zadania (quiz_id, nr, typ, tresc, czas_s, dane, etap_id)
