-- Quiz JOWES (wyścig): korekta Łukasza z 18.11 (quiz-wyscig-korekta.md). Etap 1: 8 pytań, 2: 5, 3: 5, 4: 5,
-- finał: 15 zdań prawda/fałsz (38 pytań i 4 plansze). Pytania o adres strony i organ konsultacyjno-doradczy przeszły
-- do finału, w etapie 3 doszły pytania o 30% i 87 tys. zł (z planszą z quizu klasycznego), w etapie 4 pary po 4.
-- Wiersze nadpisujemy po numerze (bez usuwania), brakujące numery 39–42 dopisujemy.
create temporary table korekta_jowes (nr int, etap int, typ text, tresc text, czas_s int, dane jsonb) on commit drop;

update public.zadania z
   set typ = k.typ, tresc = k.tresc, czas_s = k.czas_s, dane = k.dane, grafika_url = null, etap_id = e.id
  from korekta_jowes k, public.etapy e
 where z.quiz_id = (select q.id from public.quizy q join public.lokale l on l.id = q.lokal_id where l.adres_ekranu = 'jowes' and q.tytul = 'Quiz JOWES' and q.usunieto is null)
   and z.nr = k.nr
   and e.quiz_id = z.quiz_id
   and e.nr = k.etap;

select e.quiz_id, k.nr, k.typ, k.tresc, k.czas_s, k.dane, e.id
  from korekta_jowes k
  join public.etapy e on e.quiz_id = (select q.id from public.quizy q join public.lokale l on l.id = q.lokal_id where l.adres_ekranu = 'jowes' and q.tytul = 'Quiz JOWES' and q.usunieto is null) and e.nr = k.etap
 where not exists (select 1 from public.zadania z where z.quiz_id = e.quiz_id and z.nr = k.nr);

update public.etapy
   set plan_pytan = 15
 where quiz_id = (select q.id from public.quizy q join public.lokale l on l.id = q.lokal_id where l.adres_ekranu = 'jowes' and q.tytul = 'Quiz JOWES' and q.usunieto is null)
   and finalowy;
